// Typed view of site/data/guided.json, generated by `tutor site-data` from
// projects/guided/*/project.toml (src/guided.jl, `Guided.site_data`). Specs
// only: the reference, the acceptance tests and the mutants' edits are never
// exported, since `tutor guided check` keeps them hidden.
import raw from "../../site/data/guided.json";
import type { Question } from "./course";

export interface Api {
  signature: string;
  doc: string;
}

export interface Behaviour {
  id: string;
  kc: string;
  spec: string;
  hints: string[]; // level 1 only (it names the idea); levels 2 and 3 fade in from `tutor guided check`
  test_hints: string[]; // level 1 only: what a test for this behaviour checks ([] for planned projects)
}

export interface Milestone {
  id: number;
  title: string;
  goal: string;
  api: Api[];
  behaviours: Behaviour[];
  must_cover: string[];
  min_score: number;
  mutants: number;
  /** Function graded for speed and allocations against the reference ("" for none). */
  perf_entry: string;
  questions: Question[];
}

export interface GuidedProject {
  name: string;
  package: string;
  env: string;
  status: "ready" | "planned";
  title: string;
  summary: string;
  kcs: string[];
  reading: string;
  host_ok: boolean;
  packages: string[];
  milestones: Milestone[];
}

export interface GuidedData {
  julia: string;
  projects: GuidedProject[];
}

export const guided = raw as unknown as GuidedData;

/** Ready projects first, then by name (the data is sorted by name). */
export function orderedProjects(ps: GuidedProject[] = guided.projects): GuidedProject[] {
  return [...ps].sort((a, b) => (a.status === b.status ? a.name.localeCompare(b.name) : a.status === "ready" ? -1 : 1));
}

/** The commands a learner runs for a project, from the julia-tutor folder. */
export function commands(p: GuidedProject): string[] {
  const dir = `work/${p.name}`;
  return [
    `./tutor guided start ${p.name} ${dir}`,
    `./tutor guided show ${p.name} 0`,
    `./tutor guided check ${dir}` + (p.host_ok ? "" : "          # in the container (the default)"),
  ];
}
